// Minimal OSS-Fuzz reproducer driver: mimic `fuzzer [flags] file...`
// semantics by replaying each non-option file argument through
// LLVMFuzzerTestOneInput once (libFuzzer runs a provided file as a unit).
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size);

int main(int argc, char** argv)
{
    int ran = 0;
    for (int i = 1; i < argc; ++i)
    {
        if (argv[i][0] == '-' && argv[i][1] != '\0') continue; // libFuzzer flag
        FILE* f = fopen(argv[i], "rb");
        if (!f) continue;
        fseek(f, 0, SEEK_END);
        long n = ftell(f);
        fseek(f, 0, SEEK_SET);
        if (n < 0) { fclose(f); continue; }
        uint8_t* buf = (uint8_t*) malloc(n > 0 ? (size_t) n : 1);
        size_t rd = fread(buf, 1, (size_t) n, f);
        fclose(f);
        if (rd != (size_t) n) { free(buf); continue; }
        LLVMFuzzerTestOneInput(buf, (size_t) n);
        free(buf);
        ran = 1;
    }
    return ran ? 0 : 1;
}
